-- Parties organ -- generated by noctusai_lib.domain.parties.sql (do not hand-edit)

SET search_path = commerce, public;

-- Parties: one row per person/company the org deals with (PF = CPF, PJ = CNPJ). `doc` is stored without punctuation and is unique per org when present.
CREATE TABLE IF NOT EXISTS commerce.pty_parties (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id               UUID NOT NULL,
    kind                 TEXT NOT NULL CHECK (kind IN ('PF', 'PJ')),
    doc                  TEXT,
    legal_name           TEXT NOT NULL CHECK (length(btrim(legal_name)) > 0),
    trade_name           TEXT,
    email                TEXT,
    phones               JSONB NOT NULL DEFAULT '[]'::jsonb,
    address              JSONB NOT NULL DEFAULT '{}'::jsonb,
    state_registration   TEXT,
    municipal_registration TEXT,
    notes                TEXT,
    is_active            BOOLEAN NOT NULL DEFAULT true,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (id, org_id),
    CHECK (doc IS NULL OR (kind = 'PF' AND length(doc) = 11) OR (kind = 'PJ' AND length(doc) = 14)),
    CHECK (jsonb_typeof(phones) = 'array' AND jsonb_typeof(address) = 'object')
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_pty_parties_doc ON commerce.pty_parties (org_id, doc) WHERE doc IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_pty_parties_org_name ON commerce.pty_parties (org_id, lower(legal_name));
CREATE INDEX IF NOT EXISTS idx_pty_parties_org_email ON commerce.pty_parties (org_id, lower(email)) WHERE email IS NOT NULL;

ALTER TABLE commerce.pty_parties ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "pty_parties_select_own_org" ON commerce.pty_parties;
CREATE POLICY "pty_parties_select_own_org" ON commerce.pty_parties FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.pty_parties;
CREATE POLICY "service_role_bypass" ON commerce.pty_parties FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.pty_parties TO authenticated;
GRANT ALL ON commerce.pty_parties TO service_role;

-- Party roles: a party can be customer + supplier + ... at once. Unique (party, role).
CREATE TABLE IF NOT EXISTS commerce.pty_party_roles (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id      UUID NOT NULL,
    party_id    UUID NOT NULL,
    role        TEXT NOT NULL CHECK (role IN ('customer', 'supplier', 'employee', 'carrier')),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (party_id, role),
    FOREIGN KEY (party_id, org_id) REFERENCES commerce.pty_parties(id, org_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_pty_party_roles_org_role ON commerce.pty_party_roles (org_id, role);

ALTER TABLE commerce.pty_party_roles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "pty_party_roles_select_own_org" ON commerce.pty_party_roles;
CREATE POLICY "pty_party_roles_select_own_org" ON commerce.pty_party_roles FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.pty_party_roles;
CREATE POLICY "service_role_bypass" ON commerce.pty_party_roles FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.pty_party_roles TO authenticated;
GRANT ALL ON commerce.pty_party_roles TO service_role;
